def countUnpayable(coins, limit):
    coins = sorted(set(coins))
    reachable = [False] * (limit + 1)
    reachable[0] = True
    bad = 0
    for s in range(1, limit + 1):
        for c in coins:
            if c > s:
                break
            if reachable[s - c]:
                reachable[s] = True
                break
        if not reachable[s]:
            bad += 1
    return bad
